import sys,json,hashlib,collections,copy,csv,shutil,re
import numpy as np
R=Path(__file__).resolve().parents[1];sys.path.insert(0,str(R/'scripts'))
B=R/'Hardware/PoseDoll44/bench/revO22';OLD=B/'O22F4_Release';S=B/'a1mini_fins_v4/compact230';D=B/'O22F4_Compact'
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def write(p,s):p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s,encoding='utf8')
def collect(require_complete=True):
 m=json.loads((S/'stage_manifest.json').read_text());old=json.loads((OLD/'manifest.json').read_text());orig={i['object_name'].split()[0]:i for p in old['plates']for i in p['items']};parts={};plates=[];trace=[];gaps=[];edges=[]
 expected=collections.Counter((i['id'],i['original_object_name'],p['optional'])for p in old['plates']for i in p['items']);actual=collections.Counter((i['id'],i['original_object_name'],p['optional'])for p in m['plates']for i in p['items']);assert expected==actual
 for p in m['plates']:
  project=S/'projects'/f"{p['id']}_O22F4_PLA_fins.3mf";vd=S/'candidates'/('PLATE_'+p['id'])/'native/verification';proof=json.loads((vd/'plate_result.json').read_text());assert proof['native_clear']and proof['external_islands']==0 and proof['critical_external_runs']==0,(p['id'],proof);assert sha(project)==proof['project_sha256']
  if not p.get('exact_original_plate_reuse'):
   from audit_revo22_f4_compact231 import verify_profiles
   pp=verify_profiles(project,p);assert pp['all_original_effective_object_profiles_preserved'];native=json.loads((vd/'native_mesh.json').read_text());assert native['native_mesh_preserved']and native['project_sha256']==sha(project)
  plates.append({'plate':p,'source_directory':str(S),'native_project':str(project),'proof':proof})
  for idx,it in enumerate(p['items']):
   oldit=orig[it['previous_f4_address']];pid=it['id'];assert pid==oldit['id']and it['rotation_matrix']==oldit['rotation_matrix'];assert abs(it['translation_mm'][2]-oldit['translation_mm'][2])<1e-8;npz=S/'parts'/f'{pid}.npz';assert sha(npz)==sha(OLD/'parts'/npz.name)
   parts.setdefault(pid,{'source_directory':str(S),'npz_sha256':sha(npz),'plates':[]})['plates'].append(p['id']);n=np.load(npz);v=np.r_[n['v'],n['fin_v'],n['teeth_v']]@np.array(it['rotation_matrix']).T+it['translation_mm'];lo=v.min(0);hi=v.max(0);assert np.max(np.abs(np.r_[lo,hi]-it['bounds_mm']))<.00002;assert min(lo[:2])>=3.99999 and max(hi[:2])<=176.00001 and abs(lo[2])<.00001 and hi[2]<180;edges.append(float(min(*lo[:2],*(180-hi[:2]))))
   for other in p['items'][idx+1:]:
    bb=np.array(other['bounds_mm']);gap=float(np.linalg.norm(np.maximum(np.maximum(lo[:2]-bb[3:5],bb[:2]-hi[:2]),0)));assert gap>=5.99999;gaps.append(gap)
   trace.append({'id':pid,'new_address':it['object_name'].split()[0],'previous_f4_address':it['previous_f4_address'],'original_address':it['original_object_name'].split()[0],'optional':p['optional'],'npz_sha256':sha(npz),'xy_translation_mm':(np.array(it['translation_mm'])-oldit['translation_mm'])[:2].tolist(),'rotation_and_z_unchanged':True})
 assert len(parts)==150 and len(trace)==193 and len({q['previous_f4_address']for q in trace})==193 and len({q['new_address']for q in trace})==193
 result={'complete':True,'main_instances':sum(len(p['items'])for p in m['plates']if not p['optional']),'optional_instances':sum(len(p['items'])for p in m['plates']if p['optional']),'plates':plates,'parts':parts,'minimum_interobject_bbox_clearance_mm':min(gaps),'minimum_bed_edge_mm':min(edges),'trace':trace,'all_original_meshes_and_print_rotations_preserved':True,'physical_print_tested':False};assert result['main_instances']==186 and result['optional_instances']==7;write(S/'collection_status.json',json.dumps(result,ensure_ascii=False,indent=2));return result
