  record=json.loads((D/'records'/f"{row['id']}.json").read_text());record['summary']=row;write(D/'records'/f"{row['id']}.json",json.dumps(record,ensure_ascii=False,indent=2));write(D/'records'/f"{row['id']}.js",'window.AUDIT_DETAILS['+json.dumps(row['id'])+']='+json.dumps(row,ensure_ascii=False,separators=(',',':'))+';')
