 for fp in [S/'section_conversion236.json',S/'section_failure235.json',S.parent/'chronological_wall_controls104.json']:
  if fp.exists():shutil.copy2(fp,D/'verification'/fp.name)
 cp=D/'零件与打印盘对照.csv';rows=list(csv.DictReader(cp.open(encoding='utf-8-sig')))
