 replacements=[('Fxx-nn','Cxx-nn'),('F 系列','C 系列'),('新版 F 位置','新版 C 位置'),('新版 F 盘','新版 C 盘'),('表内 F 编号','表内 C 编号'),('外部 F 盘号','外部 C 盘号'),('S01 / S02 打印盘','Q01 打印盘'),('S01、S02','Q01'),('胸架 F01','胸架 C01'),('再试 F01 胸架','再试 C01 胸架'),('个别单件盘在切片器内保留 QC 开头的对象名','胸架 C01 在切片器内保留 QC 开头的对象名')]
